        #endregion private Fields
        
        /// <summary>
        /// Initializes the test data.
        /// </summary>
        [TestInitialize]
        public void Init()
        {
            // save a copy of the Excel template file to template Path
            templatePath = Path.Combine(System.Environment.CurrentDirectory, Path.GetRandomFileName() + ".xlsx");
            System.Diagnostics.Debug.WriteLine("Template path is " + templatePath);
            File.WriteAllBytes(templatePath, Properties.Resources.ProjectMap);

            fullObjectFactory = new FullObjectFactory(null, null, null, null, null, null, null, null, null, null, null, null);
            GenBOEUnityContainer.Container.RegisterInstance(typeof(IFullObjectFactory), fullObjectFactory);

            retriever = new Mock<IRetriever>();
            GenBOEUnityContainer.Container.RegisterInstance(typeof(IRetriever), retriever.Object);
            userLoader = new Mock<IUserDTODataLoader>();

            UserDTO author = new UserDTO() { DisplayName = "Tester", EmailAddress = "tester@lmco.com", UserID = 1 };
            userLoader.Setup(u => u.GetUserForActiveUser()).Returns(author);

            commonDataMapper = new Mock<ICommonDataMapper>();
            permissionsLoader = new Mock<IPermissionsDTODataLoader>();

            PerformingOrgDTO perfOrg = new PerformingOrgDTO()
            {
                IsSystemPerfOrg = false,
                PerformingOrgDesc = "P",
                PerformingOrgName = "P",
                Id = 15
            };
            retriever.Setup(x => x.GetPerformingOrgsByListId(It.IsAny<int>())).Returns(new Collection<PerformingOrgDTO>() { perfOrg });

            ResourceDTO resource1 = new ResourceDTO()
            {
                ResourceDesc = "R",
                ResourceName = "R",
                Id = 20,
                ElementOfCost = ElementOfCostType.LMLabor,
                RateType = RateType.Hours
            };
            ResourceDTO resource2 = new ResourceDTO()
            {
                ResourceDesc = "S",
                ResourceName = "S",
                Id = 30,
                ElementOfCost = ElementOfCostType.Sub,
                RateType = RateType.Cost
            };
            ResourceDTO resource3 = new ResourceDTO()
            {
                ResourceDesc = "S2",
                ResourceName = "S2",
                Id = 31,
                ElementOfCost = ElementOfCostType.Sub,
                RateType = RateType.Cost
            };
            retriever.Setup(x => x.GetResourcesByResourceListId(It.IsAny<int>())).Returns(new Collection<ResourceDTO>() { resource1, resource2, resource3 });
            retriever.Setup(x => x.GetCustomFieldsByWorkspaceId(It.IsAny<int>())).Returns(new Collection<CustomFieldDTO>());
			retriever.Setup(x => x.GetBoeTaskElementCollectionByWorkspaceId(It.IsAny<int>(), It.IsAny<bool>(), It.IsAny<int>(), It.IsAny<int>())).Returns(new Collection<BoeTaskElementDTO>());
			retriever.Setup(x => x.GetFullBoesByWorkspaceId(It.IsAny<int>(), It.IsAny<bool>(), It.IsAny<IEnumerable<BoeTaskElementDTO>>())).Returns(new List<FullBoe>() {  });
			retriever.Setup(x => x.GetOdcCollectionByWorkspaceId(It.IsAny<int>(), false)).Returns(new Collection<OtherDirectCostDTO> ());
			retriever.Setup(x => x.GetNumberOfMaterialsForBoeId(It.IsAny<int>())).Returns(0);
			retriever.Setup(x => x.GetMaterialCollectionByBoeID(It.IsAny<int>(), false)).Returns(new Collection<MaterialDTO> { });
			retriever.Setup(x => x.GetResourcesByIds(It.IsAny<ICollection<int>>())).Returns(new Collection<ResourceDTO>() { resource1, resource2, resource3 });

			SikorskyLegacyResourceDTO legacy1 = new SikorskyLegacyResourceDTO() { LegacyID = 1, LegacyResourceID = "4000W", LegacyResourceName = "iTAS STA Direct" };
            SikorskyLegacyResourceDTO legacy2 = new SikorskyLegacyResourceDTO() { LegacyID = 2, LegacyResourceID = "4046FI1", LegacyResourceName = "Management Engineering" };
            SikorskyLegacyResourceDTO legacy3 = new SikorskyLegacyResourceDTO() { LegacyID = 3, LegacyResourceID = "4045MMM", LegacyResourceName = "Standards" };
            SikorskyLegacyResourceDTO legacy4 = new SikorskyLegacyResourceDTO() { LegacyID = 4, LegacyResourceID = "4051F", LegacyResourceName = "Sys Safety Ft Worth" };

            // Setup the conversionDictionary (for imports).
            Dictionary<string, SikorskyLegacyResourceDTO> conversionDictionary = new Dictionary<string, SikorskyLegacyResourceDTO>();
            conversionDictionary.Add(legacy1.LegacyResourceID, legacy1);
            conversionDictionary.Add(legacy2.LegacyResourceID, legacy2);
            conversionDictionary.Add(legacy3.LegacyResourceID, legacy3);
            conversionDictionary.Add(legacy4.LegacyResourceID, legacy4);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyResourcesConversionDictionary()).Returns(conversionDictionary);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyResources()).Returns(new Collection<SikorskyLegacyResourceDTO> { legacy1, legacy2, legacy3, legacy4 });

            // Setup the resourceDictionary (for exports).
            Dictionary<int, SikorskyLegacyResourceDTO> resourceDictionary = new Dictionary<int, SikorskyLegacyResourceDTO>();
            resourceDictionary.Add(legacy1.LegacyID, legacy1);
            resourceDictionary.Add(legacy2.LegacyID, legacy2);
            resourceDictionary.Add(legacy3.LegacyID, legacy3);
            resourceDictionary.Add(legacy4.LegacyID, legacy4);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyResourcesDictionary(It.IsAny<bool>())).Returns(resourceDictionary);

            // Setup the Lookup Methods.
            commonDataMapper.Setup(x => x.GetSikorskyLegacyID(legacy1.LegacyResourceID, conversionDictionary)).Returns(legacy1.LegacyID);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyID(legacy2.LegacyResourceID, conversionDictionary)).Returns(legacy2.LegacyID);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyID(legacy3.LegacyResourceID, conversionDictionary)).Returns(legacy3.LegacyID);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyID(legacy4.LegacyResourceID, conversionDictionary)).Returns(legacy4.LegacyID);

            commonDataMapper.Setup(x => x.GetSikorskyLegacyResourceID(legacy1.LegacyID, resourceDictionary)).Returns(legacy1.LegacyResourceID);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyResourceID(legacy2.LegacyID, resourceDictionary)).Returns(legacy2.LegacyResourceID);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyResourceID(legacy3.LegacyID, resourceDictionary)).Returns(legacy3.LegacyResourceID);
            commonDataMapper.Setup(x => x.GetSikorskyLegacyResourceID(legacy4.LegacyID, resourceDictionary)).Returns(legacy4.LegacyResourceID);

            GenBOEUnityContainer.Container.RegisterInstance(typeof(ICommonDataMapper), commonDataMapper.Object);
            GenBOEUnityContainer.Container.RegisterInstance(typeof(IPermissionsDTODataLoader), permissionsLoader.Object);
            GenBOEUnityContainer.Container.RegisterInstance(typeof(IUserDTODataLoader), userLoader.Object);
        }

