                new ProjectMapModelView { ClassOfCost = ClassOfCost.Recurring.ToDescription(), WbsNumber = "3.05", CostCenter = "xxyy", ActivityID = "BSW1209", ActivityName = "2018 System/Software Quality Assurance", WbsElementTitle = "System/Software Quality Assurance", InitialResource = "4045MMY", StartDate = DateTime.Parse("01/02/2018"), EndDate = DateTime.Parse("12/24/2018"), Clin = "0001", SowNumber = "3.5.15", SowTitle = "Software Quality Assurance", Task = "The Contractor shall conduct on-going software quality evaluations of software development\r\nactivities and software products to assure compliance with this contract and the SDPs. The\r\nContractor shall prepare and maintain records of each software quality assurance activity. The\r\nContractor shall make these records, to include Software Development Files (SDF) available for\r\nGovernment review upon written request of the Contracting Officer. The Contractor shall make\r\nthe software quality program plan available for Government review upon written request of the\r\nContracting Officer.", Hours = 636, Dollars = 0, Rationale = "This SSQA estimate was created using the S70M-05 program actuals.  The SSQA estimate is a percentage of the engineering estimate for resources 4041TTC, 4041TTH and 4045MMS.  The SSQA resource code changed from 4049C00 to 4045MMY towards the end of the Taiwan program.  The S70M-05 actuals were obtained from COS on 10/13/2014 on project EV-BFW for the following resources.  \r\n4041TTC  32,830 hrs\r\n4041TTH  93,133 hrs\r\n4045MMS  4,629 hrs\r\n4049C      3,408 hrs\r\n4045MMY  212 hrs\r\n\r\nEstimating percentage from S70M-05 actuals = SSQA hrs / engineering hrs  = (3,408 + 212) / (32,830 + 93,133 + 4,629) = 3,620 / 130,592 = 2.8%\r\n\r\nTunisia Assault and S70M-05 are similar international programs with SEDENA building on the avionics architecture and software developed for Taiwan.\r\n\r\nThe Tunisia Assault  estimate was created using the S70M-05 estimating percentage calculated above.  Engineering hours are from the engineering AEM.  Total Tunisia Assault estimate is calculated as follows:\r\n4041TTC = 7,628 hrs total X 2.8% = 213.584 hrs\r\n4041TTH = 43,765 hrs total X 2.8% = 1,225.42 hrs\r\n4045MMS = 5,422 hrs total X 2.8% = 151.816 hrs\r\n\r\n213.584 + 1,225.42 + 151.8 hrs = 1,590.82 (rounded) hrs total SSQA support of program.\r\n1,590.82 hrs / 30 months = 53 hrs/month\r\n\r\nHours are divided up evenly between the months in 2018, 2019, and 2020\r\n2018: 53 hrs X 12 months = 636 hours\r\n2019: 53 hrs X 12 months = 636 hours\r\n2020:  53 hrs X 10 months = 530 hours\r\n\r\n\r\n", CamName = "Sawyer (Kaczor)", Category = "ENG", TieredPercentage = 1.3m},
