                new ProjectMapModelView { ClassOfCost = ClassOfCost.Recurring.ToDescription(), WbsNumber = "2.04.01.01", CostCenter = "xxyy", ActivityID = "BSW1126", ActivityName = "Configuration Status Accounting (CSA)", WbsElementTitle = "Configuration Status Accounting (CSA)", InitialResource = "4045MMV", StartDate = DateTime.Parse("03/01/2018"), EndDate = DateTime.Parse("12/24/2020"), Clin = "0001", SowNumber = "3.14", SowTitle = "Configuration Status Accounting (CSA)", Task = "The Contractor shall update and maintain the Configuration Status Accounting (CSA) database\r\nthat captures, manages, and tracks all aircraft configurations by serial number produced under\r\nthis contract. The Contractor shall prepare this CSA Information for each as-delivered\r\nTunisia Assault uniquely configured aircraft IAW DI-CMAN-81253 and deliver IAW CDRL\r\nAU71.", Hours = 320, Dollars = 0, Rationale = "Based on a total of 159 hrs to conduct a similar activity on the CH-53K program, on WBS EV-AHK.2.01.03.01.16.  It is anticipated that a complexity factor of .25 is needed for Tunisia as this effort is for a modification to an existing baseline,  where as CH-53K activity is for an entire aircraft.  The CH-53K consisted of 4 submittals averaging 40 hours per submittal (159 / 4 = 40 hours). \r\n\r\nThe delivery of the CSA will be required for each aircraft = 8 submittals \r\n8 submittals X 40 hrs per submittal = 320 hours.\r\n\r\n", CamName = "Sawyer(Beard)", Category = "ENG"},
