        /// <summary>
        /// Tests the project map export & import for non time phased workspace.
        /// </summary>
        [TestMethod]
        public void Test_ProjectMapExportImport_NonTimePhased()
        {
            ProjectMapModelView[] modelViews = this.GetProjectMapModelViews();
            FullWorkspace ws = new FullWorkspace()
            {
                ProjectMapType = ProjectMapType.NonTimePhasedProjectMap
            };
            string fileName = ProjectMapExporter.ExportToExcelFile(templatePath, modelViews, ws, false);

            try
            {
                using (FileStream f = new FileStream(fileName, FileMode.Open))
                {
                    ICollection<ProjectMapModelView> importedModelViews = ProjectMapImporter.ImportFromExcelFile(f, ProjectMapType.NonTimePhasedProjectMap);
                    AssertAreEqual(modelViews, importedModelViews, ProjectMapType.NonTimePhasedProjectMap);
                }
            }
            finally
            {
                File.Delete(fileName);
            }
        }

