        /// <summary>
        /// Asserts the equality of 2 sets of project map model views.
        /// </summary>
        /// <param name="modelViews">The model views.</param>
        /// <param name="importedModelViews">The imported model views.</param>
        /// <param name="projectMapType">Type of the project map.</param>
        private void AssertAreEqual(ProjectMapModelView[] modelViews, ICollection<ProjectMapModelView> importedModelViews, ProjectMapType projectMapType)
        {
            Assert.AreEqual(modelViews.Length, importedModelViews.Count);
            for (int i = 0; i < modelViews.Length; i++)
            {
                AssertAreEqual(modelViews[i], importedModelViews.ElementAt(i), projectMapType);
            }
        }

        /// <summary>
        /// Asserts the equality of 2 project map modelviews based on project map type.
        /// </summary>
        /// <param name="expected">The expected.</param>
        /// <param name="actual">The actual.</param>
        /// <param name="projectMapType">Type of the project map.</param>
        private void AssertAreEqual(ProjectMapModelView expected, ProjectMapModelView actual, ProjectMapType projectMapType)
        {
            // NOTE:  Our Excel utilities strips off trailing blanks and strips out \r from strings
            Assert.AreEqual(RTEUtilities.TurnHTMLIntoPlainText(expected.ActivityID), actual.ActivityID);
            Assert.AreEqual(RTEUtilities.TurnHTMLIntoPlainText(expected.ActivityName.Trim()), actual.ActivityName.Trim());
            Assert.AreEqual(expected.AddDelete ?? "A", actual.AddDelete);
            Assert.AreEqual(expected.CamName.Trim(), actual.CamName.Trim());
            Assert.AreEqual(expected.Category, actual.Category);
            Assert.AreEqual(expected.Category, actual.Category);
            Assert.AreEqual(expected.Clin, actual.Clin);
            Assert.AreEqual(expected.CostCenter, actual.CostCenter);
            Assert.AreEqual(expected.Dollars, actual.Dollars);
            Assert.AreEqual(expected.EndDate.Normalize(), actual.EndDate.Normalize());
            Assert.AreEqual(expected.Hours, actual.Hours);
            Assert.AreEqual(expected.InitialResource, actual.InitialResource);
            Assert.AreEqual(expected.LegacyID, actual.LegacyID);
            Assert.AreEqual(expected.LegacyResourceID, actual.LegacyResourceID);
            Assert.AreEqual(RTEUtilities.TurnHTMLIntoPlainText(expected.Rationale.Replace("\r", string.Empty).Trim()), actual.Rationale.Trim());
            Assert.AreEqual(expected.SowNumber, actual.SowNumber);
            Assert.AreEqual(expected.SowTitle.Trim(), actual.SowTitle.Trim());
            Assert.AreEqual(expected.StartDate.Normalize(), actual.StartDate.Normalize());
            Assert.AreEqual(RTEUtilities.TurnHTMLIntoPlainText(expected.Task.Replace("\r", string.Empty).Trim()), actual.Task.Trim());
            Assert.AreEqual(expected.WbsElementTitle, actual.WbsElementTitle);
            Assert.AreEqual(expected.WbsNumber, actual.WbsNumber);
			AssertHelpers.AssertAreEqual(expected.TieredPercentage ?? 0m, actual.TieredPercentage ?? 0m, 2);
			
            if (projectMapType == ProjectMapType.TimePhasedProjectMap)
            {
                Assert.AreEqual(expected.DiscreteMonths == null, actual.DiscreteMonths == null);
                if (expected.DiscreteMonths != null)
                {
                    Assert.AreEqual(expected.DiscreteMonths.Length, actual.DiscreteMonths.Length);
                    for (int i = 0; i < expected.DiscreteMonths.Length; i++)
                    {
                        Assert.AreEqual(expected.DiscreteMonths[i], actual.DiscreteMonths[i]);
                    }
                }
            }
            else
            {
                Assert.AreEqual(expected.Offload, actual.Offload);
            }
        }
    }
